SELECT , u.username, CASE o.order_status WHEN 0 THEN '待付款' WHEN 1 THEN '待发货' WHEN 2 THEN '待收货' WHEN 3 THEN '已完成' WHEN 4 THEN '已取消' ELSE '未知' END AS status_desc FROM tb_order o LEFT JOIN tb_user u ON o.user_id = u.user_id WHERE o.user_id = #{userId}
AND o.order_status = #{status}
ORDER BY o.create_time DESC

SELECT , u.username, CASE o.order_status WHEN 0 THEN '待付款' WHEN 1 THEN '待发货' WHEN 2 THEN '待收货' WHEN 3 THEN '已完成' WHEN 4 THEN '已取消' ELSE '未知' END AS status_desc FROM tb_order o LEFT JOIN tb_user u ON o.user_id = u.user_id
AND o.user_id = #{userId}
AND o.order_status = #{status}
AND o.create_time >= #{startTime}
AND o.create_time <= #{endTime}
ORDER BY o.create_time DESC
